#!/usr/bin/env bash
set -euo pipefail
LIVE=/var/www/web/dist
STAGING=/root/deploy-staging/web-responsive-20261105-015317
BACKUP=/root/deploy-backups/web-responsive-20261105-015317
EXPECTED=b7bee4d5f5ccedc7699665d4ef8e7997ef23f584744a93448dcc76efa3c83355
RELEASE=5a1a4a4d5026ad0af1fcfa20df005222caad0172f5e4e1b6a25934b65413bc7e
ENTRY=assets/index-e4ljJuOU.js
STAMP=web-responsive-20261105-015317
activated=0
rollback_on_error() {
  result=$?
  if [ "$result" -ne 0 ] && [ "$activated" -eq 1 ]; then
    install -m 644 "$BACKUP/dist-before/index.html" "$LIVE/.index-rollback-$STAMP.tmp"
    mv -f -- "$LIVE/.index-rollback-$STAMP.tmp" "$LIVE/index.html"
    printf 'Verification failed; restored previous index. New assets were retained.\n'
  fi
  exit "$result"
}
trap rollback_on_error EXIT
[ "$(readlink -f "$LIVE")" = /var/www/web/dist ]
[ ! -L "$LIVE/assets" ]
[ "$(sha256sum "$LIVE/index.html" | cut -d' ' -f1)" = "$EXPECTED" ]
[ "$(find "$STAGING" -type f | wc -l)" -eq 191 ]
printf '%s' '' | base64 --decode | (cd "$STAGING" && sha256sum --check --quiet -)
mkdir -p /root/deploy-backups
mkdir "$BACKUP"
cp -a -- "$LIVE" "$BACKUP/dist-before"
[ "$(sha256sum "$BACKUP/dist-before/index.html" | cut -d' ' -f1)" = "$EXPECTED" ]
printf 'Backed up previous release to %s/dist-before\n' "$BACKUP"
rsync -rlpt --checksum --backup --backup-dir="$BACKUP/replaced" --chmod=F644,D755 --exclude=/index.html "$STAGING/" "$LIVE/"
printf '%s' '' | base64 --decode | (cd "$LIVE" && sha256sum --check --quiet -)
[ "$(sha256sum "$LIVE/index.html" | cut -d' ' -f1)" = "$EXPECTED" ]
install -m 644 "$STAGING/index.html" "$LIVE/.index-$STAMP.tmp"
mv -f -- "$LIVE/.index-$STAMP.tmp" "$LIVE/index.html"
activated=1
[ "$(sha256sum "$LIVE/index.html" | cut -d' ' -f1)" = "$RELEASE" ]
curl -skf --max-time 20 --resolve portal.sugo-express.org:443:127.0.0.1 https://portal.sugo-express.org/ -o "$BACKUP/origin-index-after.html"
grep -Fq "$ENTRY" "$BACKUP/origin-index-after.html"
mv -- "$STAGING" "$BACKUP/staged"
printf 'DEPLOYED %s\nEntry: %s\nBackup: %s/dist-before\nOrigin HTTPS: 200 and correct entry\n' "$STAMP" "$ENTRY" "$BACKUP"
printf 'Rollback: rsync -rlpt %s/dist-before/ %s/\n' "$BACKUP" "$LIVE"
